import sys; sys.path.insert(0,'_exp')
from ins import ins, D
p='x2/lines.py'; s=open(p,encoding='utf-8').read()
for i in ['C30c','G03b','D06a','D06b']: assert f"'{i}'" not in s and f'"{i}"' not in s, i
blk=(
D('C30c','claude_point','加练：2024–2025 期中第 5 题，15 分。A = [[2, 1, 1], [6, 4, 5], [4, 1, 3]]。(a) LU 分解；(b) 求 X 使 AX = B；(c) rank B 和 B 的列空间。','加练一道：二零二四到二零二五学年期中，第五题，十五分。第一问，A的LU分解；第二问，求X，使A X等于B；第三问，B的秩和列空间。')+
D('C30d','claude_explain','(a)：倍数 = 下面的数 ÷ 主元。6 ÷ 2 = 3，4 ÷ 2 = 2。R₂ − 3R₁ 得 (0, 1, 2)，R₃ − 2R₁ 得 (0, −1, 1)。','第一问：倍数等于下面的数除以主元。六除以二等于三，四除以二等于二。第二行减三倍第一行，得零、一、二；第三行减两倍第一行，得零、负一、一。')+
D('C30e','claude_explain','第二列：−1 ÷ 1 = −1。R₃ − (−1)R₂，也就是 R₃ + R₂，得 (0, 0, 3)。','第二列：负一除以一，等于负一。第三行减负一倍第二行，也就是加上第二行，得零、零、三。')+
D('C30f','claude_point','倍数原样填进 L：L = [[1, 0, 0], [3, 1, 0], [2, −1, 1]]，U = [[2, 1, 1], [0, 1, 2], [0, 0, 3]]。注意那个 −1，符号别丢。','倍数原样填进L：L的下三角是三、二、负一；U就是消元的结果。注意那个负一，符号别丢。')+
D('D06a','ds_shock','(b) 要先求 A⁻¹ 吗？三阶求逆好累……','第二问，要先求A的逆吗？三阶求逆好累。',mood='panic')+
D('C30g','claude_explain','不用求逆！对 [A | B] 做同样的三步消元，B 跟着变。第 2 行：(0, 1, 0) − 3(3, 0, −1) = (−9, 1, 3)。','不用求逆！对A竖线B做同样的三步消元，B跟着一起变。第二行：零、一、零，减三倍的三、零、负一，得负九、一、三。')+
D('C30h','claude_explain','第 3 行：(0, 0, 0) − 2(3, 0, −1) = (−6, 0, 2)，再加新的第 2 行，得 (−15, 1, 5)。','第三行：零减两倍的三、零、负一，得负六、零、二；再加上新的第二行，得负十五、一、五。')+
D('C30i','claude_explain','左边已经是 U，从下往上回代：第 3 行除以 3，X 的第 3 行 = (−5, 1/3, 5/3)。','左边已经是U了，从下往上回代：第三行除以三，X的第三行是负五、三分之一、三分之五。')+
D('C30j','claude_explain','第 2 行减 2 倍第 3 行：(1, 1/3, −1/3)。第 1 行减去下面两行再除以 2：(7/2, −1/3, −7/6)。','第二行减两倍第三行，得一、三分之一、负三分之一。第一行减去下面两行，再除以二，得二分之七、负三分之一、负六分之七。')+
D('G03b','gpt_point','抽查一格：A 的第 1 行乘 X 的第 1 列：2 · 7/2 + 1 − 5 = 3，正是 B 左上角的 3。','抽查一格：A的第一行乘X的第一列：二乘二分之七，加一，减五，等于三，正是B左上角的三。')+
D('C30k','claude_explain','(c)：B 本身就是阶梯形，两个非零行，rank B = 2。列空间取主元列 (3, 0, 0)、(0, 1, 0)：第三个分量为 0 的所有向量，一整个平面。','第三问：B本身就是阶梯形，有两个非零行，秩等于二。列空间取主元列：三、零、零，和零、一、零，也就是第三个分量为零的所有向量，一整个平面。')+
D('C30l','claude_point','最后一道快题：2024–2025 期中第 3 题，10 分。5 阶矩阵，每行每列只有一个 1。判断是否非奇异，并求逆。','最后一道快题：二零二四到二零二五学年期中，第三题，十分。一个五阶矩阵，每行每列只有一个一。判断它是否非奇异，并求逆。')+
D('C30m','claude_explain','它就是单位阵换了两次行：R₁ ↔ R₃，R₄ ↔ R₅。所以 det A = (−1)(−1) = 1 ≠ 0，非奇异。','它就是单位矩阵换了两次行：第一、三行互换，第四、五行互换。所以行列式等于负一乘负一，等于一，不为零，非奇异。')+
D('C30n','claude_explain','再换一遍就换回来了：A · A = I，所以 A⁻¹ = A。不用消元，一秒出答案。','交换过的行，再换一遍就换回来了：A乘A等于单位矩阵，所以A的逆就是A自己。不用消元，一秒出答案。')+
D('D06b','ds_happy','原来逆矩阵还能是它自己！','原来逆矩阵，还能是它自己！',mood='easy')
)
ins(p,{'G03a':blk})
